const { withAppBuildGradle } = require('expo/config-plugins');

/**
 * Force APK Signature Scheme v1 + v2 + v3 on every build.
 *
 * Why: `assembleRelease` signs with the template's `debug.keystore` and, since AGP 7,
 * that produces a v2-only APK. Some OEM installers (MIUI/HyperOS among them) reject a
 * v2-only APK with the generic "Package appears to be invalid" status
 * (PackageInstaller.STATUS_FAILURE_INVALID). Enabling v1 (JAR) + v3 on top of v2 is the
 * documented compatibility fix.
 *
 * This MUST be a config plugin: `android/` is generated by `expo prebuild --clean` in CI,
 * so a hand-edited `android/app/build.gradle` would be wiped on the next build.
 *
 * The flags go on the `debug` signingConfig because the template's `release` buildType
 * reuses it (`signingConfig signingConfigs.debug`), so both build types get all three
 * schemes while the signing IDENTITY stays exactly the same (debug cert) — an update
 * still installs over an existing Tavakkol install.
 */
const FLAGS = ['enableV1Signing true', 'enableV2Signing true', 'enableV3Signing true'];

// The template writes the debug keystore block with exactly this last line.
const ANCHOR = "            keyPassword 'android'\n";

const withSigningSchemes = (config) =>
  withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') {
      throw new Error(
        'withSigningSchemes: android/app/build.gradle is not Groovy — plugin needs updating.'
      );
    }

    let contents = cfg.modResults.contents;

    if (contents.includes('enableV1Signing')) {
      return cfg; // already applied — idempotent
    }

    if (!contents.includes(ANCHOR)) {
      throw new Error(
        'withSigningSchemes: could not find the debug keystore block in android/app/build.gradle. ' +
          'The Expo template changed — update the ANCHOR in plugins/withSigningSchemes.js.'
      );
    }

    const injected = FLAGS.map((flag) => `            ${flag}\n`).join('');
    contents = contents.replace(ANCHOR, ANCHOR + injected);

    cfg.modResults.contents = contents;
    return cfg;
  });

module.exports = withSigningSchemes;
